// src/pages/page.js
import React, {  useState } from 'react';
import { graphql } from "gatsby"

import Bio from "../components/bio"
import Layout from "../components/layout"
import Seo from "../components/seo"
import Share from "../components/share"

const BlogIndex = ({ data, location }) => {
  const siteTitle = data.site.siteMetadata?.title || `Title`
  const posts = data.allFile.edges
  console.log(posts)
  const topurl="https://kyukyunyorituryo.github.io/bookshelf/"
  const [showPosts, setShowPosts] = useState(posts);
  const [inputValue, setInputValue] = useState();

  // フリーキーワードでの絞り込み
  const search = (value) => {
    if (value !== "") {
      const serchedPosts = posts.filter(
        (post) =>
          Object.values(post.node).filter(
            (item) =>
              item !== undefined &&
              item !== null &&
              item.toString().toUpperCase().indexOf(value.toString().toUpperCase()) !== -1
          ).length > 0
      );
      setShowPosts(serchedPosts);
      return;
    }

    setShowPosts(posts);
    return;
  };
    const handleInputChange = (e) => {
    setInputValue(e.target.value);
    search(e.target.value);
  };
  return (
      <Layout location={location} title={siteTitle}>
                  <h1 class="main-heading">EPUBファイルの一覧</h1>
      <div>
        <h2>フリーキーワード検索</h2>
        <input type="text" value={inputValue} onChange={handleInputChange} />
      </div>

        <h2>ファイルのダウンロード</h2>
                    <div>
                        <table border="1" cellPadding="1">
                            <th width="55%">タイトルと著者名</th>
                            <th>ダウンロード</th>
                            <th>更新日</th>
        {showPosts.map(post => {

          return (
            <tr key={post.node.name}>

                 <td> {post.node.name}</td>
                    <td align="center" ><a href={`${topurl}epub/${post.node.name}.epub`} itemProp="url">リンク</a></td><td align="center" >{post.node.modifiedTime}
                  </td>


            </tr>
          )
        })}
                        </table>
                    </div>
        <Share
          title={siteTitle}
          url={`${data.site.siteMetadata.siteUrl}`}
          />
            <Bio />
          </Layout>
  )
}

export default BlogIndex

/**
 * Head export to define metadata for the page
 *
 * See: https://www.gatsbyjs.com/docs/reference/built-in-components/gatsby-head/
 */
export const Head = () => <Seo title="青空文庫をEPUBやmobiに変換したものをおいている本棚" />

export const pageQuery = graphql`
query MyQuery {
  site {
    siteMetadata {
      title
      siteUrl
    }
  }
  allFile(
    filter: {extension: {eq: "epub"}, name: {regex: "/^.*(?<!kepub)$/"}}
    sort: {modifiedTime: DESC}
  ) {
    edges {
      node {
        name
        modifiedTime(formatString: "YYYY年MM月DD日")
      }
    }
  }
}
`
